import{_ as l,o,c as e,ae as r}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"Koala 이용약관","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ko/terms.md","filePath":"v1/ko/terms.md"}'),t={name:"v1/ko/terms.md"};function i(n,a,p,s,h,d){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="koala-이용약관" tabindex="-1"><strong>Koala</strong> 이용약관 <a class="header-anchor" href="#koala-이용약관" aria-label="Permalink to &quot;**Koala** 이용약관&quot;">​</a></h1><p>최종 업데이트: 2026년 4월 24일</p><p>시행일: 2026년 4월 24일</p><p>본 「Koala 이용약관」(이하 “본 약관”)은 【앱 운영 주체명】 및 그 관계사(이하 “당사”)와 Koala(이하 “본 앱”) 서비스를 이용하는 이용자(이하 “이용자”) 간에 체결됩니다.</p><p>본 앱을 이용하기 전에 본 약관을 신중히 읽고 충분히 이해해 주시기 바랍니다. 이용자가 “동의/수락”을 탭하거나 어떤 방식으로든 본 앱 서비스를 실제로 이용하는 경우, 이용자는 본 약관에 동의한 것으로 간주됩니다.</p><h2 id="_1-정의" tabindex="-1"><strong>1. 정의</strong> <a class="header-anchor" href="#_1-정의" aria-label="Permalink to &quot;**1. 정의**&quot;">​</a></h2><ol><li><p>본 앱: Koala 클라이언트 애플리케이션 및 관련 서비스를 의미합니다.</p></li><li><p>서비스: 당사가 본 앱을 통해 제공하는 기록(가계부), 데이터 관리, 가져오기/내보내기, 클라우드 동기화(해당되는 경우), 멤버십(해당되는 경우) 등의 기능 및 기술 서비스를 의미합니다.</p></li><li><p>계정: 이용자가 본 앱 서비스에 로그인하기 위해 사용하는 식별자(예: Apple로 로그인)를 의미합니다.</p></li></ol><h2 id="_2-약관의-범위-및-변경" tabindex="-1"><strong>2. 약관의 범위 및 변경</strong> <a class="header-anchor" href="#_2-약관의-범위-및-변경" aria-label="Permalink to &quot;**2. 약관의 범위 및 변경**&quot;">​</a></h2><ol><li><p>본 약관에는 본문 외에도 당사가 이미 게시했거나 향후 게시할 수 있는 본 앱 관련 각종 규칙, 공지, 안내 등이 포함됩니다. 해당 내용은 공식적으로 게시되는 즉시 본 약관의 일부를 구성합니다.</p></li><li><p>당사는 필요한 경우 본 약관을 변경할 수 있으며, 본 앱 또는 관련 페이지를 통해 안내할 수 있습니다. 변경 후에도 이용자가 서비스를 계속 이용하면 변경된 약관에 동의한 것으로 봅니다. 변경된 약관에 동의하지 않는 경우, 서비스 이용을 중단해야 합니다.</p></li></ol><h2 id="_3-계정-및-이용-규칙" tabindex="-1"><strong>3. 계정 및 이용 규칙</strong> <a class="header-anchor" href="#_3-계정-및-이용-규칙" aria-label="Permalink to &quot;**3. 계정 및 이용 규칙**&quot;">​</a></h2><ol><li><p>이용자는 관련 법령 및 본 약관에 따라 서비스를 이용해야 하며, 서비스를 이용하여 불법 또는 부적절한 행위를 해서는 안 됩니다.</p></li><li><p>이용자는 로그인 정보 및 기기를 안전하게 관리해야 합니다. 이용자 귀책으로 계정이 도용되거나 데이터 유출 위험이 발생한 경우, 그에 따른 책임은 이용자에게 있습니다.</p></li><li><p>제3자 계정(예: Apple)으로 로그인하는 경우, 당사는 해당 플랫폼의 규칙에 따라 필요한 인증 및 검증 절차를 수행합니다.</p></li></ol><h2 id="_4-서비스-내용-및-이용-제한" tabindex="-1"><strong>4. 서비스 내용 및 이용 제한</strong> <a class="header-anchor" href="#_4-서비스-내용-및-이용-제한" aria-label="Permalink to &quot;**4. 서비스 내용 및 이용 제한**&quot;">​</a></h2><ol><li><p>본 서비스는 “있는 그대로(AS IS)” 제공됩니다. 당사는 서비스의 안정적인 제공을 위해 노력하지만, 서비스가 중단되지 않거나 오류가 없음을 보장하지 않습니다.</p></li><li><p>이용자는 당사가 제품 개선, 운영 정책 또는 준법 요건에 따라 서비스 내용을 조정하거나 일부 기능을 중단할 수 있으며, 합리적인 범위에서 안내할 수 있음에 동의합니다.</p></li><li><p>이용자가 필수적인 약관 또는 개인정보처리방침에 동의하지 않는 경우, 본 앱의 핵심 기능을 이용하지 못하거나 서비스를 계속 이용하지 못할 수 있습니다.</p></li></ol><h2 id="_5-유료-서비스-해당되는-경우" tabindex="-1"><strong>5. 유료 서비스(해당되는 경우)</strong> <a class="header-anchor" href="#_5-유료-서비스-해당되는-경우" aria-label="Permalink to &quot;**5. 유료 서비스(해당되는 경우)**&quot;">​</a></h2><ol><li><p>본 앱은 구독/인앱 결제 등 유료 서비스(예: 멤버십 혜택)를 제공할 수 있습니다. 구체적인 내용, 가격, 기간, 자동 갱신 규칙은 구매 화면의 표시 및 관련 안내에 따릅니다.</p></li><li><p>이용자는 결제, 구독 해지, 환불 등의 규칙이 Apple App Store 등 제3자 플랫폼의 규칙에 의해 적용될 수 있음에 동의합니다.</p></li></ol><h2 id="_6-지식재산권" tabindex="-1"><strong>6. 지식재산권</strong> <a class="header-anchor" href="#_6-지식재산권" aria-label="Permalink to &quot;**6. 지식재산권**&quot;">​</a></h2><ol><li><p>본 앱 및 관련 콘텐츠(페이지 디자인, 아이콘, 텍스트, 프로그램 코드 등 포함)의 지식재산권은 당사 또는 해당 권리자에게 귀속됩니다.</p></li><li><p>당사의 사전 서면 동의 없이 본 앱 또는 콘텐츠를 어떤 형태로든 복제, 수정, 배포하거나 역공학할 수 없습니다.</p></li></ol><h2 id="_7-면책-및-책임-제한" tabindex="-1"><strong>7. 면책 및 책임 제한</strong> <a class="header-anchor" href="#_7-면책-및-책임-제한" aria-label="Permalink to &quot;**7. 면책 및 책임 제한**&quot;">​</a></h2><ol><li><p>불가항력, 제3자 사유, 네트워크 환경, 기기 장애 등으로 인해 서비스 이용이 불가하거나 데이터 이상이 발생한 경우, 당사는 법령이 허용하는 범위에서 그로 인한 손해에 대해 책임을 지지 않습니다.</p></li><li><p>이용자는 기록 데이터 및 가져오기/내보내기 파일 등의 백업을 스스로 유지해야 합니다. 백업 미실시로 인한 데이터 손실에 대해 당사는 법령이 허용하는 범위에서 책임을 지지 않습니다.</p></li></ol><h2 id="_8-개인정보-보호" tabindex="-1"><strong>8. 개인정보 보호</strong> <a class="header-anchor" href="#_8-개인정보-보호" aria-label="Permalink to &quot;**8. 개인정보 보호**&quot;">​</a></h2><ol><li><p>당사는 이용자의 개인정보 보호를 중요하게 생각합니다. 이용자가 서비스를 이용하는 경우, 당사는 「Koala 개인정보처리방침」에 따라 이용자의 개인정보를 처리합니다.</p></li><li><p>「Koala 개인정보처리방침」은 본 약관의 중요한 일부를 구성하며 본 약관과 동일한 법적 효력을 가집니다.</p></li></ol><h2 id="_9-준거법-및-분쟁-해결" tabindex="-1"><strong>9. 준거법 및 분쟁 해결</strong> <a class="header-anchor" href="#_9-준거법-및-분쟁-해결" aria-label="Permalink to &quot;**9. 준거법 및 분쟁 해결**&quot;">​</a></h2><ol><li><p>본 약관의 체결, 이행, 해석 및 분쟁 해결에는 중화인민공화국의 법령(저촉법 규정 제외)이 적용됩니다.</p></li><li><p>본 약관과 관련하여 발생하는 분쟁은 당사자 간의 협의로 해결하도록 노력합니다. 협의로 해결되지 않는 경우, 어느 당사자든 【계약 이행지/운영 주체 소재지】 관할 인민법원에 소를 제기할 수 있습니다.</p></li></ol><h2 id="_10-문의하기" tabindex="-1"><strong>10. 문의하기</strong> <a class="header-anchor" href="#_10-문의하기" aria-label="Permalink to &quot;**10. 문의하기**&quot;">​</a></h2><p>본 약관에 관한 문의, 의견 또는 제안이 있으시면 아래로 연락해 주세요.</p><p>● 운영 주체: Koala</p><p>● 문의 이메일: <a href="mailto:ruanweidev@163.com" target="_blank" rel="noreferrer">ruanweidev@163.com</a></p><h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1>',28)])])}const u=l(t,[["render",i]]);export{c as __pageData,u as default};
